from __future__ import annotations

import base64
import shutil
import subprocess
import sys
import traceback
from datetime import datetime
from pathlib import Path

PROJECT = Path(r"C:\PhoCap")
APP = PROJECT / "app"
ROUTER = APP / "routers" / "data_tools.py"
TEMPLATE = APP / "templates" / "data_tools" / "survey_cleanup.html"
EXPORTS = PROJECT / "exports"

STAMP = datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP = EXPORTS / f"backup_source_bai_13b_10_v3_18b6_{STAMP}"

MARK_ROUTER = "BAI_13B_10_V3_18B6_SCOPE_BY_COMMUNE"
MARK_TEMPLATE = "BAI_13B_10_V3_18B6_SCOPE_UI"

def dec(value: str) -> str:
    return base64.b64decode(value).decode("utf-8")

BUILD_OLD = dec("")
BUILD_NEW = dec("")
SCOPE_HELPERS = dec("")
LIVE_OLD = dec("")
LIVE_NEW = dec("")
REMAIN_OLD = dec("")
REMAIN_NEW = dec("")
CTX_PLAN_OLD = dec("ICAgICAgICB5ZWFyX3BsYW4gPSBfYnVpbGRfZGVsZXRlX3BsYW4oCiAgICAgICAgICAgIGNvbiwKICAgICAgICAgICAgeWVhcl9jb2RlPVRBUkdFVF9ZRUFSX0NPREUsCiAgICAgICAgKQo=")
CTX_PLAN_NEW = dec("")
CTX_RET_OLD = dec("ICAgICAgICAieWVhcl9wbGFuIjogeWVhcl9wbGFuX3B1YmxpYywKICAgICAgICAiY2xlYW51cF9zdGF0dXMiOiBjbGVhbnVwX3N0YXR1cywKICAgICAgICAiYmFja3VwX25hbWUiOiBiYWNrdXBfbmFtZSwKICAgICAgICAiZXJyb3JfbWVzc2FnZSI6IGVycm9yX21lc3NhZ2UsCiAgICB9Cg==")
CTX_RET_NEW = dec("ICAgICAgICAieWVhcl9wbGFuIjogeWVhcl9wbGFuX3B1YmxpYywKICAgICAgICAidGFyZ2V0X2NvbW11bmVzIjogdGFyZ2V0X2NvbW11bmVzLAogICAgICAgICJjbGVhbnVwX3N0YXR1cyI6IGNsZWFudXBfc3RhdHVzLAogICAgICAgICJiYWNrdXBfbmFtZSI6IGJhY2t1cF9uYW1lLAogICAgICAgICJlcnJvcl9tZXNzYWdlIjogZXJyb3JfbWVzc2FnZSwKICAgIH0K")
POST_SIG_OLD = dec("ZGVmIGV4ZWN1dGVfc3VydmV5X2NsZWFudXAoCiAgICByZXF1ZXN0OiBSZXF1ZXN0LAogICAgY29uZmlybV90ZXh0OiBzdHIgPSBGb3JtKGRlZmF1bHQ9IiIpLAogICAgY29uZmlybV9zY29wZTogc3RyID0gRm9ybShkZWZhdWx0PSIiKSwKICAgIGNvbmZpcm1fYWxsX2NvbW11bmVzOiBzdHIgPSBGb3JtKGRlZmF1bHQ9IiIpLAopOg==")
POST_SIG_NEW = dec("")
CONFIRM_OLD = dec("")
CONFIRM_NEW = dec("")
POST_PLAN_OLD = dec("")
POST_PLAN_NEW = dec("")
SCOPE_UI = dec("")
SCOPE_JS = dec("")


def read_text(path: Path) -> str:
    if not path.exists():
        raise RuntimeError(f"Không tìm thấy: {path}")
    return path.read_text(encoding="utf-8-sig")


def backup() -> None:
    for src in (ROUTER, TEMPLATE):
        dst = BACKUP / src.relative_to(PROJECT)
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)


def restore() -> None:
    for target in (ROUTER, TEMPLATE):
        src = BACKUP / target.relative_to(PROJECT)
        if src.exists():
            shutil.copy2(src, target)


def clear_cache() -> None:
    for cache in APP.rglob("__pycache__"):
        if cache.is_dir():
            shutil.rmtree(cache, ignore_errors=True)


def patch_router(text: str) -> str:
    if MARK_ROUTER in text and "batch_ids_override" in text:
        return text

    required = [
        BUILD_OLD,
        LIVE_OLD,
        REMAIN_OLD,
        CTX_PLAN_OLD,
        CTX_RET_OLD,
        POST_SIG_OLD,
        CONFIRM_OLD,
        POST_PLAN_OLD,
    ]

    missing = [
        str(index + 1)
        for index, block in enumerate(required)
        if block not in text
    ]

    if missing:
        raise RuntimeError(
            "data_tools.py không đúng nền V3.18B5 "
            "ở các điểm: " + ", ".join(missing)
        )

    text = text.replace(BUILD_OLD, BUILD_NEW, 1)

    anchor = "def _count_preserved(con: sqlite3.Connection) -> dict[str, int]:"
    if anchor not in text:
        raise RuntimeError(
            "Không tìm thấy _count_preserved để chèn helper scope."
        )

    text = text.replace(
        anchor,
        SCOPE_HELPERS + anchor,
        1,
    )

    text = text.replace(LIVE_OLD, LIVE_NEW, 1)
    text = text.replace(REMAIN_OLD, REMAIN_NEW, 1)
    text = text.replace(CTX_PLAN_OLD, CTX_PLAN_NEW, 1)
    text = text.replace(CTX_RET_OLD, CTX_RET_NEW, 1)
    text = text.replace(POST_SIG_OLD, POST_SIG_NEW, 1)
    text = text.replace(CONFIRM_OLD, CONFIRM_NEW, 1)
    text = text.replace(POST_PLAN_OLD, POST_PLAN_NEW, 1)

    return text


def patch_template(text: str) -> str:
    if MARK_TEMPLATE in text:
        return text

    start_marker = "<!-- === BAI_13B_10_V3_18B5_SELECT_ALL_COMMUNES === -->"
    end_marker = '                    <label class="confirm-check">'

    start = text.find(start_marker)
    if start < 0:
        raise RuntimeError(
            "Không tìm thấy block chọn toàn bộ của V3.18B5."
        )

    end = text.find(end_marker, start)
    if end < 0:
        raise RuntimeError(
            "Không tìm thấy điểm kết thúc block V3.18B5."
        )

    text = text[:start] + SCOPE_UI + text[end:]

    # Xóa JavaScript B5 cũ nếu có.
    old_js_anchor = "window.pcSelectAllCommunes = function"
    pos = text.find(old_js_anchor)

    if pos >= 0:
        script_start = text.rfind("<script>", 0, pos)
        script_end = text.find("</script>", pos)

        if script_start >= 0 and script_end >= 0:
            script_end += len("</script>")
            text = text[:script_start] + text[script_end:]

    if "</body>" not in text:
        raise RuntimeError(
            "Template thiếu </body>."
        )

    text = text.replace(
        "</body>",
        SCOPE_JS + "\n</body>",
        1,
    )

    return text


def verify() -> None:
    subprocess.run(
        [sys.executable, "-m", "py_compile", str(ROUTER)],
        cwd=PROJECT,
        check=True,
    )

    from jinja2 import Environment, FileSystemLoader

    env = Environment(
        loader=FileSystemLoader(str(APP / "templates"))
    )
    env.get_template("data_tools/survey_cleanup.html")

    router = read_text(ROUTER)
    template = read_text(TEMPLATE)

    for item in (
        MARK_ROUTER,
        "batch_ids_override",
        "def _target_communes_for_year",
        "def _batch_ids_for_communes",
        "def _scope_from_form",
        'mode == "single"',
        'mode == "multi"',
        'mode == "all"',
        'batch_ids_override=set(plan["batch_ids"])',
        "remaining_forms = 0",
        "protected_target_tables",
    ):
        if item not in router:
            raise RuntimeError(
                f"Router B6 thiếu: {item}"
            )

    for item in (
        MARK_TEMPLATE,
        'value="single"',
        'value="multi"',
        'value="all"',
        "Một xã/phường",
        "Chọn nhiều xã/phường",
        "Toàn bộ",
        "pcCheckAllCommunes",
        "pcUncheckAllCommunes",
        "scope_all_warning",
    ):
        if item not in template:
            raise RuntimeError(
                f"Template B6 thiếu: {item}"
            )


def main() -> int:
    print("=" * 110)
    print(
        "BÀI 13B-10 V3.18B6 - "
        "SỬA PHẠM VI DỌN THEO XÃ/PHƯỜNG"
    )
    print("=" * 110)
    print()
    print("B6 có 3 phạm vi:")
    print(" 1. Một xã/phường: đúng xã của đợt đang chọn.")
    print(" 2. Chọn nhiều xã/phường: checkbox từng xã.")
    print(" 3. Toàn bộ 130 xã/phường: phải chủ động chọn riêng.")
    print()
    print("Backend DELETE dùng đúng batch_ids của phạm vi đã chọn.")
    print("survey_batches vẫn được giữ nguyên.")
    print("Vùng bảo vệ B4 vẫn giữ nguyên.")
    print()
    print("CÀI B6 KHÔNG XÓA DỮ LIỆU.")
    print()

    if not ROUTER.exists() or not TEMPLATE.exists():
        raise RuntimeError(
            "Không tìm thấy data_tools.py hoặc survey_cleanup.html."
        )

    current_router = read_text(ROUTER)
    current_template = read_text(TEMPLATE)

    for marker in (
        "BAI_13B_10_V3_18B4_PROTECTED_DOMAINS",
        "BAI_13B_10_V3_18B5_CONFIRM_ALL_COMMUNES",
    ):
        if marker not in current_router:
            raise RuntimeError(
                f"Source hiện tại thiếu nền bắt buộc: {marker}"
            )

    if "BAI_13B_10_V3_18B5_SELECT_ALL_COMMUNES" not in current_template:
        raise RuntimeError(
            "Template hiện tại không phải nền V3.18B5."
        )

    EXPORTS.mkdir(parents=True, exist_ok=True)
    BACKUP.mkdir(parents=True, exist_ok=False)
    backup()
    print("Backup source:", BACKUP)

    try:
        ROUTER.write_text(
            patch_router(current_router),
            encoding="utf-8",
        )
        TEMPLATE.write_text(
            patch_template(current_template),
            encoding="utf-8",
        )

        verify()
        clear_cache()

        print()
        print("CÀI ĐẶT BÀI 13B-10 V3.18B6 THÀNH CÔNG")
        print()
        print("CÀI XONG CHƯA XÓA DỮ LIỆU.")
        print("Khởi động lại Uvicorn và Ctrl+F5.")
        print("Kiểm tra Cửa Lò ở chế độ Một xã/phường trước.")
        return 0

    except Exception:
        traceback.print_exc()
        print()
        print("CÓ LỖI - ĐANG KHÔI PHỤC V3.18B5...")
        restore()
        clear_cache()
        print("ĐÃ KHÔI PHỤC SOURCE TRƯỚC V3.18B6.")
        print("Backup:", BACKUP)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
